Code: 
<code>
use strict;
use warnings;

my $ip="";
my $io;

while (<>) {
    if (/blocked.using/) {
        do {
            $io = <>;
            $ip = $2 if $io =~ /(\d+)\s+(\S+)/;
            print $ip;
            #adding to database;
        } until ($io !~ /(\d+)\s+(\S+)/);
   }

    if (/Relay.access.denied/) {
        do {
            $io = <>;
            $ip = $2 if $io =~ /(\d+)\s+(\S+)/;
            print $ip;
            # adding to database;
        } until ($io !~ /(\d+)\s+(\S+)/);
    }
}
</code>
